1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	  }
38	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
39	  .p-I { background-color: #22d3ee; }
40	  .p-O { background-color: #facc15; }
41	  .p-T { background-color: #a855f7; }
42	  .p-S { background-color: #22c55e; }
43	  .p-Z { background-color: #ef4444; }
44	  .p-J { background-color: #3b82f6; }
45	  .p-L { background-color: #f97316; }
46	  .ghost-I { box-shadow: inset 0 0 0 2px #22d3ee; }
47	  .ghost-O { box-shadow: inset 0 0 0 2px #facc15; }
48	  .ghost-T { box-shadow: inset 0 0 0 2px #a855f7; }
49	  .ghost-S { box-shadow: inset 0 0 0 2px #22c55e; }
50	  .ghost-Z { box-shadow: inset 0 0 0 2px #ef4444; }
51	  .ghost-J { box-shadow: inset 0 0 0 2px #3b82f6; }
52	  .ghost-L { box-shadow: inset 0 0 0 2px #f97316; }
53	  .pause-btn {
54	    width: 100%;
55	    padding: 8px;
56	    font: inherit;
57	    font-size: 14px;
58	    color: #e5e7eb;
59	    background: #1f2937;
60	    border: 1px solid #374151;
61	    border-radius: 6px;
62	    cursor: pointer;
63	  }
64	  .pause-btn:disabled { opacity: 0.5; cursor: default; }
65	  .panel { width: 160px; }
66	  .stat { margin-bottom: 14px; }
67	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
68	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
69	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
70	  .overlay {
71	    position: absolute;
72	    inset: 0;
73	    display: flex;
74	    flex-direction: column;
75	    align-items: center;
76	    justify-content: center;
77	    background: rgba(17, 24, 39, 0.8);
78	    font-size: 22px;
79	    font-weight: 600;
80	  }
81	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
82	</style>
83	</head>
84	<body>
85	<div class="game">
86	  <div class="board-wrap">
87	    <div class="board" id="board" data-testid="board"></div>
88	    <div class="overlay" id="overlay" data-testid="game-over" hidden>Game over<small>Press Enter to play again</small></div>
89	    <div class="overlay" id="paused" data-testid="paused-indicator" hidden>Paused<small>Press P to resume</small></div>
90	  </div>
91	  <div class="panel">
92	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
93	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
94	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
95	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
96	    <div class="stat"><div class="label">Hold</div><div id="hold" class="mini" data-testid="hold-piece" data-piece=""></div></div>
97	    <button type="button" class="pause-btn" id="pause-btn" data-testid="pause-btn">Pause</button>
98	    <div class="help">
99	      ← → move<br>
100	      ↑ rotate<br>
101	      ↓ soft drop<br>
102	      Space hard drop<br>
103	      C hold<br>
104	      P pause<br>
105	      Enter new game
106	    </div>
107	  </div>
108	</div>
109	<script>
110	(function () {
111	  "use strict";
112	
113	  var ROWS = 20;
114	  var COLS = 10;
115	  var PREVIEW = 1; // [REQ-006] show only the next piece
116	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
117	
118	  // Spawn orientation of each piece inside its rotation box.
119	  var SHAPES = {
120	    I: ["....", "IIII", "....", "...."],
121	    O: ["OO", "OO"],
122	    T: [".T.", "TTT", "..."],
123	    S: [".SS", "SS.", "..."],
124	    Z: ["ZZ.", ".ZZ", "..."],
125	    J: ["J..", "JJJ", "..."],
126	    L: ["..L", "LLL", "..."]
127	  };
128	
129	  // Scoring (decision): points for rows cleared at once, times level. Clearing rows
130	  // together always beats clearing them one at a time. Soft drop 1 per cell, hard drop 2.
131	  var LINE_POINTS = [0, 100, 300, 500, 800];
132	  var SOFT_DROP_POINTS = 1;
133	  var HARD_DROP_POINTS = 2;
134	
135	  var state = {
136	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
137	    current: null,  // { type, matrix, row, col }
138	    next: [],
139	    bag: [],
140	    score: 0,
141	    level: 1,
142	    lines: 0,
143	    hold: null,     // letter of the held piece, or null
144	    canHold: true,  // false once the current piece has used its hold
145	    status: "running"
146	  };
147	
148	  var timer = null;
149	  var timerDue = 0;        // when the pending gravity step fires
150	  var pausedRemaining = 0; // time left on that step when the game was paused
151	
152	  // ---------- pieces ----------
153	
154	  function isType(t) { return TYPES.indexOf(t) !== -1; }
155	
156	  function randomType() {
157	    if (state.bag.length === 0) {
158	      var bag = TYPES.slice();
159	      for (var i = bag.length - 1; i > 0; i--) {
160	        var j = Math.floor(Math.random() * (i + 1));
161	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
162	      }
163	      state.bag = bag;
164	    }
165	    return state.bag.pop();
166	  }
167	
168	  function cleanQueue(queue) {
169	    if (!Array.isArray(queue)) return [];
170	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
171	  }
172	
173	  function fillPreview() {
174	    while (state.next.length < PREVIEW) state.next.push(randomType());
175	  }
176	
177	  function makeMatrix(type) {
178	    return SHAPES[type].map(function (r) { return r.split(""); });
179	  }
180	
181	  function pieceCells(piece) {
182	    var cells = [];
183	    for (var r = 0; r < piece.matrix.length; r++) {
184	      for (var c = 0; c < piece.matrix[r].length; c++) {
185	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
186	      }
187	    }
188	    return cells;
189	  }
190	
191	  function fits(matrix, row, col) {
192	    for (var r = 0; r < matrix.length; r++) {
193	      for (var c = 0; c < matrix[r].length; c++) {
194	        if (matrix[r][c] === ".") continue;
195	        var br = row + r, bc = col + c;
196	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
197	        if (state.board[br][bc] !== ".") return false;
198	      }
199	    }
200	    return true;
201	  }
202	
203	  // [REQ-001] [REQ-004] [REQ-007] Spawn the next piece, or the given one (from hold);
204	  // the game ends if it has nowhere to go.
205	  function spawn(fromHold) {
206	    var type = fromHold || (state.next.length ? state.next.shift() : randomType());
207	    fillPreview();
208	    var matrix = makeMatrix(type);
209	    var top = 0;
210	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
211	    var piece = {
212	      type: type,
213	      matrix: matrix,
214	      row: -top,
215	      col: Math.floor((COLS - matrix[0].length) / 2),
216	      lockTicks: 0,
217	      lockResets: 0
218	    };
219	    if (!fits(piece.matrix, piece.row, piece.col)) {
220	      state.current = null;
221	      state.status = "gameover";
222	      stopTimer();
223	      return;
224	    }
225	    state.current = piece;
226	  }
227	
228	  // ---------- core rules ----------
229	
230	  // [REQ-003] [REQ-007] Remove full rows, drop the rest, score by rows cleared at once times
231	  // level. The level rises by one each time the line total crosses a multiple of 10, so it
232	  // carries on from a level set by setLevel and never goes down.
233	  function clearLines() {
234	    var kept = state.board.filter(function (row) {
235	      return row.some(function (ch) { return ch === "."; });
236	    });
237	    var cleared = ROWS - kept.length;
238	    while (kept.length < ROWS) kept.unshift(emptyRow());
239	    state.board = kept;
240	    if (cleared > 0) {
241	      state.score += LINE_POINTS[cleared] * state.level;
242	      var before = Math.floor(state.lines / 10);
243	      state.lines += cleared;
244	      state.level += Math.floor(state.lines / 10) - before;
245	    }
246	  }
247	
248	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
249	  function lockPiece() {
250	    var p = state.current;
251	    pieceCells(p).forEach(function (cell) {
252	      state.board[cell[0]][cell[1]] = p.type;
253	    });
254	    state.current = null;
255	    state.canHold = true;
256	    clearLines();
257	    spawn();
258	  }
259	
260	  // [REQ-007] Hold: put the falling piece aside and take the next one, or swap with the
261	  // held piece. Once per piece until a piece locks.
262	  function hold() {
263	    if (!state.canHold) return;
264	    var type = state.current.type;
265	    var held = state.hold;
266	    state.hold = type;
267	    state.canHold = false;
268	    state.current = null;
269	    spawn(held);
270	  }
271	
272	  function tryMove(dr, dc) {
273	    var p = state.current;
274	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
275	    p.row += dr;
276	    p.col += dc;
277	    return true;
278	  }
279	
280	  // Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
281	  // lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
282	  // resting restarts the delay, at most MAX_LOCK_RESETS times per piece. A soft drop on a
283	  // resting piece restarts it too, from the same budget.
284	  var LOCK_DELAY = 2;
285	  var MAX_LOCK_RESETS = 3;
286	
287	  function isResting(p) {
288	    return !fits(p.matrix, p.row + 1, p.col);
289	  }
290	
291	  // [REQ-002] [REQ-005] Restart the lock delay if the piece has restarts left.
292	  function restartLockDelay(p) {
293	    if (p.lockResets < MAX_LOCK_RESETS) {
294	      p.lockResets++;
295	      p.lockTicks = 0;
296	    }
297	  }
298	
299	  // [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
300	  // Used by the real timer, by tick(n) and by soft drop. Returns true if the piece fell.
301	  function gravityStep() {
302	    if (state.status !== "running" || !state.current) return false;
303	    var p = state.current;
304	    if (tryMove(1, 0)) {
305	      p.lockTicks = 0;
306	      return true;
307	    }
308	    p.lockTicks++;
309	    if (p.lockTicks >= LOCK_DELAY) lockPiece();
310	    return false;
311	  }
312	
313	  // [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
314	  function shift(dc) {
315	    var p = state.current;
316	    var resting = isResting(p);
317	    if (!tryMove(0, dc)) return;
318	    if (resting) restartLockDelay(p);
319	  }
320	
321	  // [REQ-003] [REQ-005] Soft drop: fall one row for a point. On a resting piece it scores
322	  // nothing and restarts the lock delay like a sideways move, instead of counting a tick.
323	  function softDrop() {
324	    var p = state.current;
325	    if (isResting(p)) {
326	      restartLockDelay(p);
327	      return;
328	    }
329	    tryMove(1, 0);
330	    p.lockTicks = 0;
331	    state.score += SOFT_DROP_POINTS;
332	  }
333	
334	  // [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
335	  function rotate() {
336	    var p = state.current;
337	    if (!p) return;
338	    var size = p.matrix.length;
339	    var rotated = [];
340	    for (var r = 0; r < size; r++) {
341	      rotated.push([]);
342	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
343	    }
344	    var kicks = [0, -1, 1, -2, 2];
345	    for (var i = 0; i < kicks.length; i++) {
346	      if (fits(rotated, p.row, p.col + kicks[i])) {
347	        p.matrix = rotated;
348	        p.col += kicks[i];
349	        return;
350	      }
351	    }
352	  }
353	
354	  // [REQ-009] Landing cells of the falling piece: where a hard drop would put it.
355	  function ghostCells() {
356	    var p = state.current;
357	    if (!p) return [];
358	    var row = p.row;
359	    while (fits(p.matrix, row + 1, p.col)) row++;
360	    return pieceCells({ matrix: p.matrix, row: row, col: p.col });
361	  }
362	
363	  // [REQ-009] Pause or resume. The piece keeps its lock ticks and restarts, and the pending
364	  // gravity step resumes with the time it had left, so pausing never buys lock time.
365	  function togglePause() {
366	    if (state.status === "running") {
367	      pausedRemaining = timer !== null ? Math.max(0, timerDue - Date.now()) : gravityInterval();
368	      stopTimer();
369	      state.status = "paused";
370	    } else if (state.status === "paused") {
371	      state.status = "running";
372	      startTimer(pausedRemaining);
373	    }
374	    render();
375	  }
376	
377	  // [REQ-001] [REQ-003] [REQ-009] Player actions; soft and hard drop score per cell moved down.
378	  // Nothing but "pause" works while paused.
379	  function input(action) {
380	    if (action === "pause") { togglePause(); return; }
381	    if (state.status !== "running" || !state.current) return;
382	    switch (action) {
383	      case "left": shift(-1); break;
384	      case "right": shift(1); break;
385	      case "softDrop": softDrop(); break;
386	      case "hardDrop":
387	        var dropped = 0;
388	        while (tryMove(1, 0)) dropped++;
389	        state.score += dropped * HARD_DROP_POINTS;
390	        lockPiece();
391	        break;
392	      case "rotate":
393	      case "rotateCW": rotate(); break;
394	      case "hold": hold(); break;
395	      default: return;
396	    }
397	    render();
398	    restartTimerIfNeeded();
399	  }
400	
401	  // ---------- timer ----------
402	
403	  // [REQ-007]
404	  function gravityInterval() {
405	    return Math.max(100, 1000 - (state.level - 1) * 100);
406	  }
407	
408	  function stopTimer() {
409	    if (timer !== null) { clearTimeout(timer); timer = null; }
410	  }
411	
412	  // [REQ-009] delay defaults to a full gravity interval; resume passes the time left.
413	  function startTimer(delay) {
414	    stopTimer();
415	    if (state.status !== "running") return;
416	    var ms = delay === undefined ? gravityInterval() : delay;
417	    timerDue = Date.now() + ms;
418	    timer = setTimeout(function () {
419	      timer = null;
420	      gravityStep();
421	      render();
422	      startTimer();
423	    }, ms);
424	  }
425	
426	  function restartTimerIfNeeded() {
427	    if (state.status === "running" && timer === null) startTimer();
428	  }
429	
430	  // ---------- setup ----------
431	
432	  function emptyRow() {
433	    var row = [];
434	    for (var c = 0; c < COLS; c++) row.push(".");
435	    return row;
436	  }
437	
438	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
439	  function newGame(queue) {
440	    state.board = [];
441	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
442	    state.bag = [];
443	    state.score = 0;
444	    state.level = 1;
445	    state.lines = 0;
446	    state.hold = null;
447	    state.canHold = true;
448	    state.status = "running";
449	    state.current = null;
450	    state.next = cleanQueue(queue);
451	    fillPreview();
452	    spawn();
453	    render();
454	    startTimer();
455	  }
456	
457	  // ---------- rendering (synchronous) ----------
458	
459	  var boardEl = document.getElementById("board");
460	  var nextEl = document.getElementById("next");
461	  var holdEl = document.getElementById("hold");
462	  var scoreEl = document.getElementById("score");
463	  var levelEl = document.getElementById("level");
464	  var linesEl = document.getElementById("lines");
465	  var overlayEl = document.getElementById("overlay");
466	  var pausedEl = document.getElementById("paused");
467	  var pauseBtn = document.getElementById("pause-btn");
468	  var cellEls = [];
469	
470	  (function buildBoard() {
471	    for (var r = 0; r < ROWS; r++) {
472	      cellEls.push([]);
473	      for (var c = 0; c < COLS; c++) {
474	        var el = document.createElement("div");
475	        el.className = "cell";
476	        el.setAttribute("data-testid", "cell");
477	        el.setAttribute("data-row", String(r));
478	        el.setAttribute("data-col", String(c));
479	        el.setAttribute("data-filled", "false");
480	        el.setAttribute("data-piece", "");
481	        el.setAttribute("data-ghost", "false");
482	        boardEl.appendChild(el);
483	        cellEls[r].push(el);
484	      }
485	    }
486	  })();
487	
488	  // [REQ-009] A ghost cell gets an outline in the piece colour but stays unfilled.
489	  function paintCell(el, type, ghostType) {
490	    el.className = type ? "cell p-" + type : ghostType ? "cell ghost-" + ghostType : "cell";
491	    el.setAttribute("data-filled", type ? "true" : "false");
492	    el.setAttribute("data-piece", type || "");
493	    el.setAttribute("data-ghost", !type && ghostType ? "true" : "false");
494	  }
495	
496	  // [REQ-004] [REQ-007] Fill a 4x2 mini grid with a piece (or leave it empty), board colours.
497	  function fillMini(grid, type) {
498	    grid.textContent = "";
499	    grid.setAttribute("data-piece", type || "");
500	    var rows = type ? SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; }) : [];
501	    for (var r = 0; r < 2; r++) {
502	      for (var c = 0; c < 4; c++) {
503	        var cell = document.createElement("div");
504	        var ch = rows[r] ? rows[r].charAt(c) : ".";
505	        cell.className = type && ch === type ? "mini-cell p-" + type : "mini-cell";
506	        grid.appendChild(cell);
507	      }
508	    }
509	  }
510	
511	  // [REQ-004] [REQ-006] The next piece only, coloured as on the board.
512	  function renderPreview() {
513	    nextEl.textContent = "";
514	    state.next.slice(0, PREVIEW).forEach(function (type) {
515	      var grid = document.createElement("div");
516	      grid.className = "mini";
517	      grid.setAttribute("data-testid", "next-piece-item");
518	      fillMini(grid, type);
519	      nextEl.appendChild(grid);
520	    });
521	  }
522	
523	  // [REQ-001] [REQ-009] Draw the whole game state into the DOM, immediately.
524	  function render() {
525	    var drawn = state.board.map(function (row) { return row.slice(); });
526	    var ghost = state.board.map(function () { return []; });
527	    if (state.current) {
528	      var type = state.current.type;
529	      ghostCells().forEach(function (cell) {
530	        ghost[cell[0]][cell[1]] = type;
531	      });
532	      pieceCells(state.current).forEach(function (cell) {
533	        drawn[cell[0]][cell[1]] = type;
534	      });
535	    }
536	    for (var r = 0; r < ROWS; r++) {
537	      for (var c = 0; c < COLS; c++) {
538	        var ch = drawn[r][c];
539	        paintCell(cellEls[r][c], ch === "." ? "" : ch, ghost[r][c]);
540	      }
541	    }
542	    scoreEl.textContent = String(state.score);
543	    levelEl.textContent = String(state.level);
544	    linesEl.textContent = String(state.lines);
545	    overlayEl.hidden = state.status !== "gameover";
546	    pausedEl.hidden = state.status !== "paused";
547	    pauseBtn.textContent = state.status === "paused" ? "Resume" : "Pause";
548	    pauseBtn.disabled = state.status === "gameover";
549	    renderPreview();
550	    fillMini(holdEl, state.hold);
551	  }
552	
553	  // ---------- keyboard ----------
554	
555	  document.addEventListener("keydown", function (e) {
556	    var map = {
557	      ArrowLeft: "left",
558	      ArrowRight: "right",
559	      ArrowDown: "softDrop",
560	      ArrowUp: "rotateCW",
561	      " ": "hardDrop",
562	      c: "hold",
563	      C: "hold",
564	      Shift: "hold",
565	      p: "pause",
566	      P: "pause",
567	      Escape: "pause"
568	    };
569	    if (e.key === "Enter") {
570	      e.preventDefault();
571	      newGame();
572	      return;
573	    }
574	    if (map[e.key]) {
575	      e.preventDefault();
576	      input(map[e.key]);
577	    }
578	  });
579	
580	  // [REQ-009] Blur after the click so Space and Enter keep driving the game, not the button.
581	  pauseBtn.addEventListener("click", function () {
582	    input("pause");
583	    pauseBtn.blur();
584	  });
585	
